package cl.nexbyte.siger.custodia;
import java.nio.file.*;import java.security.*;import java.time.*;import java.util.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import static org.junit.jupiter.api.Assertions.*;
import tools.jackson.databind.json.JsonMapper;
class AcreditacionAlmacenWindowsTest {
 @TempDir Path temp;Path a,b;KeyPair ti;JsonMapper mapper=JsonMapper.builder().build();Instant now=Instant.parse("2026-10-25T12:00:00Z");Clock clock=Clock.fixed(now,ZoneOffset.UTC);
 AcreditacionAlmacenWindows.Topologia topology=new AcreditacionAlmacenWindows.Topologia("NTFS_LOCAL_V1","QA","V1","D1","V2","D2");
 @BeforeEach void setup()throws Exception{a=temp.resolve("a");b=temp.resolve("b");ArchivoAgente.directorio(a);ArchivoAgente.directorio(b);ti=KeyPairGenerator.getInstance("Ed25519").generateKeyPair();}
 AcreditacionAlmacenWindows.Evidencia evidence(AcreditacionAlmacenWindows.Topologia t,Instant expiry,String failure,String report){return new AcreditacionAlmacenWindows.Evidencia("1.0",t,a.toString(),b.toString(),"dominio-origen",failure,"TI-SOLO-SINTETICO",report,now.minusSeconds(120),now.minusSeconds(60),expiry);}
 FirmaOperativa seal(AcreditacionAlmacenWindows.Evidencia e){return FirmaOperativa.firmar(e,AcreditacionAlmacenWindows.DOMAIN,"ti-sintetico",ti.getPrivate(),mapper);}
 AcreditacionAlmacenWindows.Resultado check(AcreditacionAlmacenWindows.Evidencia e,AcreditacionAlmacenWindows.Topologia observed){return AcreditacionAlmacenWindows.verificar(seal(e),Map.of("ti-sintetico",ti.getPublic()),a,b,clock,mapper,(x,y)->observed);}
 @Test void evidenciaFirmadaTopologiaVigenteYRestauracionPermitenSoloPreparacion(){var r=check(evidence(topology,now.plusSeconds(3600),"dominio-respaldo","a".repeat(64)),topology);assertTrue(r.acreditada());assertTrue(r.codigo().endsWith("EMISION_AUN_BLOQUEADA"));}
 @Test void dosVolumenesDelMismoDiscoSiempreSeRechazan(){var t=new AcreditacionAlmacenWindows.Topologia("NTFS_LOCAL_V1","QA","V1","D1","V2","D1");assertFalse(check(evidence(t,now.plusSeconds(3600),"otro","a".repeat(64)),t).acreditada());}
 @Test void topologiaCambiadaODominioCompartidoNoSeAceptan(){var e=evidence(topology,now.plusSeconds(3600),"dominio-origen","a".repeat(64));assertFalse(check(e,topology).acreditada());var other=new AcreditacionAlmacenWindows.Topologia("NTFS_LOCAL_V1","OTRO","V1","D1","V2","D2");assertFalse(check(evidence(topology,now.plusSeconds(3600),"otro","a".repeat(64)),other).acreditada());}
 @Test void vencidaLargaOSinRestauracionSeRechaza(){assertFalse(check(evidence(topology,now.minusSeconds(1),"otro","a".repeat(64)),topology).acreditada());assertFalse(check(evidence(topology,now.plus(Duration.ofDays(91)),"otro","a".repeat(64)),topology).acreditada());assertFalse(check(evidence(topology,now.plusSeconds(3600),"otro",""),topology).acreditada());}
 @Test void firmaOTipoNoConfiableNoPuedeAcreditar()throws Exception{var e=evidence(topology,now.plusSeconds(3600),"otro","a".repeat(64));var impostor=KeyPairGenerator.getInstance("Ed25519").generateKeyPair();assertFalse(AcreditacionAlmacenWindows.verificar(seal(e),Map.of("ti-sintetico",impostor.getPublic()),a,b,clock,mapper,(x,y)->topology).acreditada());var remote=new AcreditacionAlmacenWindows.Topologia("REMOTO_NO_IMPLEMENTADO","QA","V1","D1","V2","D2");assertFalse(check(evidence(remote,now.plusSeconds(3600),"otro","a".repeat(64)),remote).acreditada());}
 @Test void ningunaConfiguracionBooleanaHabilitaLaIndependencia(){var p=new Properties();p.setProperty("garantia.independiente","true");assertFalse(AcreditacionAlmacenWindows.inspeccionar(p,a,b,clock,mapper).acreditada());p.setProperty("garantia.windows.emision-habilitada","true");p.setProperty("garantia.windows.autorizacion-referencia","SIN-ACREDITACION");assertThrows(java.io.IOException.class,()->AcreditacionAlmacenWindows.autorizar(p,a,b));}
}
